import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Label } from '../ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select';
import { Copy, Check } from 'lucide-react';
import axios from 'axios';
import { clientService } from '../../services/clientService';

const API = process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000';

export const InviteUserModal = ({ isOpen, onClose, onSuccess }) => {
  const [formData, setFormData] = useState({
    email: '',
    role: 'user',
    client_id: null,
  });
  const [loading, setLoading] = useState(false);
  const [invitationLink, setInvitationLink] = useState(null);
  const [copied, setCopied] = useState(false);
  const [clients, setClients] = useState([]);

  useEffect(() => {
    if (isOpen && formData.role === 'client') {
      loadClients();
    }
  }, [isOpen, formData.role]);

  const loadClients = async () => {
    try {
      const data = await clientService.getAll();
      setClients(data);
    } catch (error) {
      console.error('Error loading clients:', error);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        `${API}/api/invitations`,
        formData,
        { headers: { Authorization: `Bearer ${token}` }}
      );

      setInvitationLink(response.data.invitation.invitation_url);
      alert('Invitación enviada por email exitosamente');
      onSuccess();
    } catch (error) {
      alert(error.response?.data?.detail || 'Error al enviar invitación');
    } finally {
      setLoading(false);
    }
  };

  const handleCopyLink = () => {
    navigator.clipboard.writeText(invitationLink);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleClose = () => {
    setFormData({ email: '', role: 'user', client_id: null });
    setInvitationLink(null);
    setCopied(false);
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>Invitar Nuevo Usuario</DialogTitle>
        </DialogHeader>

        {!invitationLink ? (
          <form onSubmit={handleSubmit}>
            <div className="space-y-4 py-4">
              <div>
                <Label htmlFor="email">Email *</Label>
                <Input
                  id="email"
                  name="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  required
                  placeholder="usuario@ejemplo.com"
                />
                <p className="text-xs text-gray-500 mt-1">
                  Se enviará un email con el link de registro
                </p>
              </div>

              <div>
                <Label htmlFor="role">Rol *</Label>
                <Select 
                  value={formData.role} 
                  onValueChange={(value) => setFormData({ ...formData, role: value, client_id: null })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="admin">Administrador</SelectItem>
                    <SelectItem value="user">Usuario (Consultor)</SelectItem>
                    <SelectItem value="client">Cliente</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {formData.role === 'client' && (
                <div>
                  <Label htmlFor="client_id">Cliente Asociado *</Label>
                  <Select 
                    value={formData.client_id || undefined} 
                    onValueChange={(value) => setFormData({ ...formData, client_id: value })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Seleccionar cliente..." />
                    </SelectTrigger>
                    <SelectContent>
                      {clients.map((client) => (
                        <SelectItem key={client._id} value={client._id}>
                          {client.company_name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              )}
            </div>

            <DialogFooter>
              <Button type="button" variant="outline" onClick={handleClose}>
                Cancelar
              </Button>
              <Button type="submit" disabled={loading} className="bg-green-600 hover:bg-green-700">
                {loading ? 'Enviando...' : 'Enviar Invitación'}
              </Button>
            </DialogFooter>
          </form>
        ) : (
          <div className="py-4">
            <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-4">
              <p className="text-green-800 font-medium mb-2">
                ✓ Invitación enviada exitosamente
              </p>
              <p className="text-sm text-green-700">
                Se ha enviado un email a <strong>{formData.email}</strong> con el link de registro.
              </p>
            </div>

            <div>
              <Label>Link de invitación (válido por 7 días)</Label>
              <div className="flex gap-2 mt-2">
                <Input
                  value={invitationLink}
                  readOnly
                  className="font-mono text-sm"
                />
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleCopyLink}
                  className="shrink-0"
                >
                  {copied ? (
                    <Check className="w-4 h-4 text-green-600" />
                  ) : (
                    <Copy className="w-4 h-4" />
                  )}
                </Button>
              </div>
              <p className="text-xs text-gray-500 mt-1">
                También puedes copiar y compartir este link manualmente
              </p>
            </div>

            <DialogFooter className="mt-6">
              <Button onClick={handleClose} className="bg-green-600 hover:bg-green-700">
                Cerrar
              </Button>
            </DialogFooter>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
};
